CREATE TABLE IF NOT EXISTS measurements_normalized (
    session_id TEXT,
    measurement_type TEXT,
    measurement_value REAL,
    measurement_time DATETIME,
    PRIMARY KEY (session_id, measurement_type, measurement_time)
);

INSERT INTO measurements_normalized (session_id, measurement_type, measurement_value, measurement_time)
SELECT session_id, 'cognitive_score' AS measurement_type, cognitive_score AS measurement_value, recorded_at AS measurement_time
FROM measurements WHERE status = 'valid';

INSERT INTO measurements_normalized (session_id, measurement_type, measurement_value, measurement_time)
SELECT session_id, 'reaction_ms' AS measurement_type, reaction_ms AS measurement_value, recorded_at AS measurement_time
FROM measurements WHERE status = 'valid';

